--
-- Estructura de tabla para la tabla `catalogocuentas`
--

CREATE TABLE `catalogocuentas` (
  `cuentaId` int(10) NOT NULL COMMENT 'Llave primaria y única autoincremental',
  `movimientoId` int(10) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla de movimientos y de esa manera establecer si la cuenta tendra movimientos o no',
  `tipoSaldoId` int(11) DEFAULT NULL COMMENT 'Llave foranea parqa la conexion con la tabla tipoDeSaldo y de esa manera escoger que tipo de saldo sera la cuenta',
  `numeroCuenta` varchar(255) DEFAULT NULL COMMENT 'El numero que se asignara a la cuenta el cual sera unico y no se podra repetir',
  `cuentaDependiente` varchar(255) DEFAULT NULL COMMENT 'la cuenta que esta depende si un dado caso es una cuneta principal este campo sera 0',
  `nivelCuenta` char(50) DEFAULT NULL COMMENT 'el nivel de la cuenta que estamos creado',
  `nombreCuenta` varchar(255) DEFAULT NULL COMMENT 'El nombre que se le asignara ha la cuenta',
  `usuarioAgrega` varchar(255) DEFAULT NULL COMMENT 'Estos aparatados estan para ayudarnos a manejar la bitacora y llevar un mejor control de las acciones de los usuarios',
  `fechaAgrega` datetime DEFAULT NULL COMMENT 'Estos aparatados estan para ayudarnos a manejar la bitacora y llevar un mejor control de las acciones de los usuarios',
  `usuarioModifica` varchar(255) DEFAULT NULL COMMENT 'Estos aparatados estan para ayudarnos a manejar la bitacora y llevar un mejor control de las acciones de los usuarios',
  `fechaModifica` datetime DEFAULT NULL COMMENT 'Estos aparatados estan para ayudarnos a manejar la bitacora y llevar un mejor control de las acciones de los usuarios'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

