--
-- Estructura de tabla para la tabla `partidaDetalle`
--

CREATE TABLE `partidaDetalle` (
  `partidaDetalleId` int(10) NOT NULL COMMENT 'Llave primaria auto incremental para la identificación del dato a ingresar',
  `partidaId` int(11) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla partidas',
  `cuentaId` int(10) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla cuentas y de esa manera cargar las cuentas que tendrán movimientos ',
  `tipoComprobanteId` int(10) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla comprobantes',
  `cargo` decimal(10,2) DEFAULT 0.00 COMMENT 'El monto del cargo que se le aplicara ha la cuenta',
  `abono` decimal(10,2) DEFAULT 0.00 COMMENT 'El monto del abono que se le aplicara a la cuenta',
  `saldo` decimal(10,2) DEFAULT NULL,
  `numeroComprobante` int(100) DEFAULT NULL COMMENT 'El numero de comprobante que se entrego al contador',
  `fechaComprobante` date DEFAULT NULL COMMENT 'la fecha en la cual fue emitido este comprobante',
  `concepto` varchar(255) DEFAULT NULL COMMENT 'concepto especifico opcional',
  `usuarioAgrega` varchar(255) DEFAULT NULL COMMENT 'campo para el registro de movimientos en el sistema',
  `fechaAgrega` date DEFAULT NULL COMMENT 'campo para el registro de movimientos en el sistema',
  `usuarioModifica` varchar(255) DEFAULT NULL COMMENT 'campo para el registro de movimientos en el sistema',
  `fechaModifica` datetime DEFAULT NULL COMMENT 'campo para el registro de movimientos en el sistema'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

