--
-- Estructura de tabla para la tabla `partidas`
--

CREATE TABLE `partidas` (
  `partidaId` int(11) NOT NULL COMMENT 'Llave primaria auto incremental para la identificación del dato a ingresar',
  `tipoPartidaId` int(11) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla tipoPartida ',
  `estadoId` int(11) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla saldo y de esa manera manejar el estado de la partida si esta abierta, saldada o cerrada|saldada',
  `codigoPartida` varchar(255) NOT NULL COMMENT 'Código auto generado por el sistema que sera único y el identificador de la partida',
  `fechacontable` date NOT NULL COMMENT 'Fecha contable que se esta trabajando ',
  `concepto` varchar(255) NOT NULL COMMENT 'Concepto general de la partida ',
  `debe` decimal(12,2) DEFAULT NULL COMMENT 'calculo de la suma del movimientos en partida detalle',
  `haber` decimal(12,2) DEFAULT NULL COMMENT 'calculo de la suma del movimientos en partida detalle',
  `diferencia` decimal(12,2) DEFAULT NULL COMMENT 'Diferencia de los campos del debe y haber',
  `mayorizada` int(10) DEFAULT NULL COMMENT '1=NO, 2=SI',
  `fechaActual` date NOT NULL COMMENT 'fecha actual en la que se registra la partida',
  `usuarioAgrega` varchar(255) NOT NULL COMMENT 'campos para el control de los movimientos en el sistema',
  `fechaAgrega` datetime NOT NULL COMMENT 'campos para el control de los movimientos en el sistema',
  `usuarioModifica` varchar(255) NOT NULL COMMENT 'campos para el control de los movimientos en el sistema',
  `fechaModifica` datetime NOT NULL COMMENT 'campos para el control de los movimientos en el sistema'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

