--
-- Estructura de tabla para la tabla `periodo`
--

CREATE TABLE `periodo` (
  `periodoId` int(10) NOT NULL COMMENT 'Llave primaria auto incremental para la identificación del dato a ingresar',
  `anio` varchar(10) DEFAULT NULL COMMENT 'se ingresa el año a trabajar',
  `mes` varchar(10) DEFAULT NULL COMMENT 'se ingresa el mes a trabajar',
  `estadoId` int(50) DEFAULT NULL COMMENT 'Llave foranea para la conexion con la tabla estados y nos permite establecer si este periodo esta abierto o cerrado',
  `usuarioAgrega` varchar(255) DEFAULT NULL COMMENT 'campo para el registro de los movimientos del sistema',
  `fechaAgrega` date DEFAULT NULL COMMENT 'campo para el registro de los movimientos del sistema',
  `usuarioModifica` varchar(255) DEFAULT NULL COMMENT 'campo para el registro de los movimientos del sistema',
  `fechaModifica` datetime DEFAULT NULL COMMENT 'campo para el registro de los movimientos del sistema'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

