--
-- Estructura de tabla para la tabla `saldo`
--

CREATE TABLE `saldo` (
  `saldoId` int(10) NOT NULL COMMENT 'Llave primaria auto incremental para la identificación del dato a ingresar',
  `cuentaId` int(10) NOT NULL COMMENT 'Llave foranea para la conexion con la tabla cuenta y de esa manera asignar el saldo a la cuenta especifica',
  `debe` decimal(10,2) DEFAULT NULL COMMENT 'Sumatoria de la cantidad del debe que ha tenido esta cuenta',
  `haber` decimal(10,2) DEFAULT NULL COMMENT 'Sumatoria de la cantidad del haber que ha tenido esta cuenta',
  `fecha` date DEFAULT NULL COMMENT 'fecha en la cual se esta guardando el saldo',
  `saldo` decimal(10,2) DEFAULT NULL COMMENT 'el calculo total de la cuenta dependiendo si esta es acreedor o deudor se realiza la operacion y se guarda en este campo',
  `saldoDia` decimal(10,2) DEFAULT NULL COMMENT 'saldo que tiene en el día ',
  `SaldoAnterior` decimal(10,2) DEFAULT NULL COMMENT 'saldo que tenia anterior de los nuevos movimientos '
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

--
-- Volcado de datos para la tabla `saldo`
